/**
 * aria-cross-device-sync — Authenticated cross-device session memory sync
 *  POST { event:'push', email, token, device_id, turns, device_meta? }
 *    -> merges device turns into the email-keyed master log
 *  POST { event:'pull', email, token, since? }
 *    -> returns master log entries newer than `since`
 *  POST { event:'devices', email, token }
 *    -> lists devices that have synced
 *
 *  Token = HMAC of email signed with APERTURE_JWT_SECRET. Generated by /aria-magic-link.
 *  Uses Netlify Blobs. Last 200 turns kept. PII redacted before persist.
 *  Cat 21 — Knowledge graph + memory (cross-device).
 */
const crypto = require('crypto');
const { redact } = require('./_pii-redact');

const SECRET = process.env.APERTURE_JWT_SECRET || 'changeme-dev';

let _blobs = null;
async function getStore() {
  if (_blobs !== null) return _blobs;
  try {
    const { getStore } = require('@netlify/blobs');
    _blobs = getStore({ name: 'aria-cross-device', consistency: 'strong' });
  } catch { _blobs = false; }
  return _blobs;
}

function hashEmail(e) {
  return crypto.createHash('sha256').update(String(e || '').toLowerCase().trim()).digest('hex').slice(0, 32);
}
function makeToken(email) {
  return crypto.createHmac('sha256', SECRET).update(email.toLowerCase().trim()).digest('hex').slice(0, 32);
}
function verifyToken(email, token) {
  if (!email || !token) return false;
  const expect = makeToken(email);
  if (expect.length !== token.length) return false;
  return crypto.timingSafeEqual(Buffer.from(expect), Buffer.from(token));
}

const MAX_TURNS = 200;

exports.handler = async (event) => {
  const headers = {
    'Access-Control-Allow-Origin': 'https://iisupp.net',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
    'Content-Type': 'application/json'
  };
  if (event.httpMethod === 'OPTIONS') return { statusCode: 204, headers, body: '' };
  if (event.httpMethod !== 'POST') return { statusCode: 405, headers, body: JSON.stringify({ error: 'POST only' }) };

  let body;
  try { body = JSON.parse(event.body || '{}'); }
  catch { return { statusCode: 400, headers, body: JSON.stringify({ error: 'invalid JSON' }) }; }

  const email = String(body.email || '').toLowerCase().trim();
  const token = String(body.token || '');
  if (!email || !/.+@.+\..+/.test(email)) return ok({ ok: false, error: 'valid email required' });
  if (!verifyToken(email, token)) return { statusCode: 401, headers, body: JSON.stringify({ ok: false, error: 'invalid_token', hint: 'request via /aria-magic-link' }) };

  const tk = hashEmail(email);
  const store = await getStore();
  const ev = String(body.event || '').trim();

  if (ev === 'push') {
    const deviceId = String(body.device_id || 'unknown').slice(0, 40);
    const turns = Array.isArray(body.turns) ? body.turns : [];
    if (!turns.length) return ok({ ok: false, error: 'no turns' });

    // Load master, merge by ts, dedupe
    let master = (store ? await store.get('master-' + tk, { type: 'json' }) : null) || { turns: [], devices: {}, updated_at: 0 };
    const sanitized = turns
      .filter(t => t && (t.role === 'user' || t.role === 'assistant'))
      .map(t => ({
        role: t.role,
        content: redact(String(t.content || '')).slice(0, 2000),
        ts: Number(t.ts) || Date.now(),
        device: deviceId
      }));

    // Merge: avoid exact duplicates by ts+role+content
    const seen = new Set(master.turns.map(t => t.ts + '|' + t.role + '|' + t.content.slice(0, 60)));
    sanitized.forEach(t => {
      const k = t.ts + '|' + t.role + '|' + t.content.slice(0, 60);
      if (!seen.has(k)) { master.turns.push(t); seen.add(k); }
    });

    master.turns.sort((a, b) => a.ts - b.ts);
    master.turns = master.turns.slice(-MAX_TURNS);
    master.devices[deviceId] = {
      last_sync: Date.now(),
      meta: body.device_meta || {}
    };
    master.updated_at = Date.now();

    if (store) await store.setJSON('master-' + tk, master);

    return ok({
      ok: true,
      merged: sanitized.length,
      total_turns: master.turns.length,
      devices: Object.keys(master.devices).length,
      durable: !!store
    });
  }

  if (ev === 'pull') {
    const since = Number(body.since || 0);
    let master = (store ? await store.get('master-' + tk, { type: 'json' }) : null) || { turns: [], devices: {}, updated_at: 0 };
    const filtered = since > 0 ? master.turns.filter(t => t.ts > since) : master.turns;
    return ok({
      ok: true,
      turns: filtered,
      master_updated_at: master.updated_at,
      total_turns: master.turns.length
    });
  }

  if (ev === 'devices') {
    let master = (store ? await store.get('master-' + tk, { type: 'json' }) : null) || { devices: {} };
    return ok({
      ok: true,
      devices: Object.entries(master.devices).map(([id, d]) => ({
        id,
        last_sync: d.last_sync,
        meta: d.meta
      }))
    });
  }

  return { statusCode: 400, headers, body: JSON.stringify({ error: 'unknown event' }) };

  function ok(b) { return { statusCode: 200, headers, body: JSON.stringify(b) }; }
};

// Expose token generator for testing
module.exports._test_makeToken = makeToken;
